INSERT INTO parks (slug, name, category, region, province, municipality, description, latitude, longitude, status)
VALUES ('sotos-y-bosques-de-ribera-de-canaverosa', 'Sotos y bosques de ribera de Cañaverosa', 'Reserva Natural', 'Región de Murcia', 'Murcia', 'Calasparra y Moratalla', 'El bosque de ribera mejor conservado del Segura: una galería cerrada de álamos, sauces y tarays a lo largo del río, entre Calasparra y Moratalla.', 38.28027, -1.71834, 'available')
ON DUPLICATE KEY UPDATE
