    SELECT 'zonas-subestepicas-de-6220', '6220', 'Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea', 'Pastos', 'Pastizales secos en los que conviven gramíneas vivaces de mata dura, como el lastón (Brachypodium retusum) o el esparto, con una multitud de plantas anuales diminutas que nacen con las lluvias y se secan antes del verano. En agosto parecen un erial pardo; en abril pueden reunir cuarenta especies distintas en un metro cuadrado. Esa riqueza escondida es la razón de que sea un hábitat prioritario.', 1, 38.286752, -1.713074, '#66cdaa', '{"type":"MultiPolygon","coordinates":[[[[-1.731046,38.279331],[-1.729359,38.279533],[-1.727472,38.279418],[-1.725399,38.27931],[-1.724299,38.279343],[-1.723437,38.279735],[-1.722458,38.280202],[-1.72223,38.280361],[-1.722132,38.280383],[-1.721885,38.280488],[-1.721653,38.280589],[-1.721449,38.280704],[-1.721173,38.280877],[-1.720955,38.281014],[-1.720906,38.281045],[-1.720338,38.281143],[-1.719387,38.281173],[-1.719225,38.28114],[-1.718949,38.281056],[-1.718703,38.280976],[-1.718412,38.280874],[-1.718263,38.280859],[-1.717826,38.28071],[-1.716753,38.280689],[-1.716218,38.280832],[-1.715883,38.280842],[-1.715264,38.280768],[-1.714148,38.280525],[-1.713961,38.280483],[-1.712465,38.280273],[-1.711922,38.280195],[-1.711828,38.28023],[-1.710503,38.280697],[-1.709449,38.282155],[-1.709026,38.283195],[-1.709084,38.284066],[-1.709767,38.285037],[-1.711053,38.286264],[-1.712203,38.287083],[-1.712568,38.287772],[-1.712631,38.28843],[-1.712624,38.288475],[-1.712614,38.288538],[-1.712345,38.289346],[-1.712325,38.289387],[-1.712219,38.289606],[-1.71208,38.289853],[-1.711978,38.290036],[-1.711832,38.290323],[-1.711701,38.290551],[-1.711585,38.290735],[-1.71141,38.291008],[-1.711206,38.291294],[-1.710987,38.291571],[-1.710798,38.291799],[-1.710653,38.29195],[-1.710463,38.292155],[-1.710303,38.292302],[-1.710143,38.292463],[-1.709953,38.292587],[-1.709571,38.292632],[-1.708701,38.292451],[-1.708036,38.292061],[-1.70701,38.291