    SELECT 'galerias-y-matorrales-92D0', '92D0', 'Galerías y matorrales ribereños termomediterráneos (Nerio-Tamaricetea)', 'Ribera', 'La vegetación leñosa de ramblas, arroyos y ríos de caudal irregular, que unos meses llevan agua y otros son un lecho de piedras: adelfares y tarayales. La adelfa (Nerium oleander), de hojas coriáceas y flores rosas, y los tarays (Tamarix), de ramillas finas y flores en espiga, resisten tanto las avenidas violentas como meses de sequía. Toda la adelfa es muy tóxica, incluidas hojas y ramas secas.', 0, 38.271551, -1.729941, '#2e8b57', '{"type":"MultiPolygon","coordinates":[[[[-1.731931,38.278696],[-1.73193,38.278516],[-1.731739,38.278383],[-1.731426,38.278186],[-1.731146,38.278012],[-1.730648,38.277754],[-1.730234,38.277335],[-1.729947,38.276967],[-1.729714,38.276455],[-1.72951,38.275948],[-1.729399,38.274694],[-1.729469,38.274271],[-1.729523,38.273948],[-1.729577,38.273592],[-1.729769,38.273157],[-1.730063,38.272638],[-1.730176,38.272342],[-1.730386,38.271826],[-1.730597,38.271391],[-1.730691,38.271194],[-1.730837,38.270902],[-1.730954,38.270412],[-1.730989,38.270156],[-1.730894,38.269745],[-1.730842,38.269627],[-1.730558,38.26934],[-1.730181,38.269075],[-1.729782,38.268809],[-1.729592,38.26873],[-1.729243,38.268839],[-1.728699,38.269068],[-1.72786,38.269221],[-1.727116,38.269159],[-1.72653,38.268886],[-1.726388,38.26879],[-1.726255,38.268771],[-1.725856,38.268694],[-1.725564,38.268606],[-1.725349,38.26854],[-1.724982,38.268365],[-1.724937,38.268342],[-1.724408,38.268025],[-1.723693,38.267707],[-1.723532,38.267633],[-1.722843,38.266751],[-1.722755,38.265705],[-1.722432,38.264841],[-1.721804,38.264131],[-1.720967,38.263658],[-1.72034,38.263488],[-1.720275,38.263497],[-1.72012,38.263522],[-1.719211,38.26367],[-1.718097,38.26387],[-1.716949,38.263762],[-1.715835,38.263313],[-1.714835,38.262518],[-1.714225,38.261142],[-1.713985,38.260301],[-1.713974,38.26026],[-1.713494,38.259732],[-1.712902,38.259347],[-1.711559,38.258994],[-1.711521,38.2