    SELECT 'bosques-galeria-de-92A0', '92A0', 'Bosques galería de Salix alba y Populus alba', 'Ribera', 'Alamedas y saucedas: la banda de árboles de hoja caduca que acompaña a los ríos, con el álamo blanco de envés plateado, chopos y sauces de raíces dentro del agua. Dan sombra al cauce, sujetan las orillas en las crecidas y sostienen una fauna que no aparece a veinte metros de allí. Es un bosque estrecho y alargado que funciona además como corredor entre sierras.', 0, 38.268924, -1.731178, '#6b8e23', '{"type":"Polygon","coordinates":[[[-1.733923,38.279087],[-1.733918,38.278349],[-1.733909,38.278303],[-1.733893,38.278246],[-1.733892,38.278242],[-1.733851,38.278115],[-1.733831,38.278063],[-1.733806,38.278007],[-1.733781,38.277962],[-1.733658,38.277752],[-1.733653,38.277743],[-1.733632,38.277711],[-1.733558,38.277599],[-1.733366,38.277423],[-1.733024,38.277189],[-1.732666,38.276956],[-1.732303,38.276735],[-1.732061,38.276612],[-1.732042,38.276608],[-1.732039,38.276607],[-1.732026,38.276605],[-1.732017,38.27659],[-1.732014,38.276588],[-1.731873,38.276442],[-1.73175,38.276283],[-1.731598,38.275953],[-1.731478,38.275654],[-1.731462,38.275481],[-1.731454,38.275458],[-1.731436,38.275415],[-1.731435,38.27541],[-1.731409,38.275355],[-1.731379,38.275301],[-1.731362,38.275274],[-1.731359,38.275242],[-1.731353,38.27518],[-1.731349,38.275143],[-1.731337,38.275085],[-1.731321,38.275028],[-1.731301,38.274971],[-1.731275,38.274915],[-1.731245,38.274861],[-1.731241,38.274854],[-1.731239,38.274819],[-1.731238,38.274812],[-1.731232,38.274753],[-1.731221,38.274695],[-1.731214,38.274669],[-1.731174,38.274522],[-1.731176,38.27452],[-1.731228,38.274478],[-1.731276,38.274433],[-1.73132,38.274385],[-1.731361,38.274336],[-1.731387,38.274299],[-1.731443,38.274217],[-1.731453,38.274202],[-1.731485,38.274148],[-1.731501,38.274115],[-1.731527,38.273947],[-1.731621,38.273736],[-1.731908,38.273222],[-1.731909,38.273219],[-1.731912,38.273197],[-1.731935,38.273162],[-1.731944,38.273147],[-1.732049,3