INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, iucn_spain, spain_status, regional_status, regional_ccaa, review_note, eidos_taxonid, gbif_species_key, gbif_occurrences, zepa_site_code, is_migratory, site_presence)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.iucn_spain, s.spain_status, s.regional_status, s.regional_ccaa, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.gbif_occurrences, s.zepa_site_code, s.is_migratory, s.site_presence
FROM parks pk JOIN (
    SELECT 'Ardilla roja' common_name, 'Sciurus vulgaris' scientific_name, 'fauna' kingdom, 'Roedor' family, 'Pinares y bosques con arbolado maduro y producción de piñones o frutos' primary_habitat, 'LC' conservation_status, 'Ardilla arborícola de cola larga y esponjosa y orejas con pinceles de pelo más marcados en invierno. En los pinares mediterráneos su rastro más evidente son las piñas roídas hasta dejar solo el eje, abandonadas en tocones y piedras.' description, NULL description_source, 'Piñas roídas hasta el raspón, apiladas en un mismo posadero; Cola larga y esponjosa que mantiene erguida al saltar; Pinceles de pelo en las orejas, sobre todo en invierno' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eichh%C3%B6rnchen_D%C3%BCsseldorf_Hofgarten_edit.jpg?width=1280' image_url, 'Ray eye (CC BY-SA 2.0 de) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 1 rarity_local, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}' rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'GBIF: 6 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas' source, 'Chordata' taxon_phylum, 'Mammalia' taxon_class, 'Rodentia' taxon_order, 'Sciuridae' taxon_family, 'Sciurus' taxon_genus, 'LC (Preocupación menor) (evaluación UICN 2023)' iucn_global, 'LC — Preocupación menor (Lista Roja española, 2007)' iucn_spain, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)' regional_status, 'Región de Murcia' regional_ccaa, NULL review_note, 12414 eidos_taxonid, 8211070 gbif_species_key, 6 gbif_occurrences, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Lagartija colilarga', 'Psammodromus algirus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Protegida (LESRPE)', 'Lagartija esbelta de escamas grandes, quilladas y brillantes, con dos líneas claras muy marcadas a cada lado del dorso. La cola puede medir el doble que el cuerpo. Los machos lucen en primavera manchas azules en el hombro y las mejillas anaranjadas.', NULL, 'Dos líneas claras nítidas a lo largo de cada costado; Escamas grandes y quilladas, de aspecto brillante; Cola larguísima, hasta el doble que el cuerpo', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_algirus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'LC', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10670, 2469763, 3, NULL, NULL, NULL
    UNION ALL
    SELECT 'Aladierno', 'Rhamnus alaternus', 'flora', 'Arbusto', 'Matorral alto, encinares y barrancos sobre suelos pedregosos', 'Interés especial', 'Arbusto perennifolio de hojas alternas, coriáceas y de borde finamente dentado, sin espinas. Sus frutos maduran de rojo a negro y son muy buscados por los pájaros. Se distingue del espino negro por carecer de espinas y tener hojas mayores.', NULL, 'Sin espinas, a diferencia de otros ramnos; Hojas alternas, coriáceas y algo dentadas; Frutos que pasan de rojo a negro al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_alaternus1627.JPG?width=1280', 'tato grasso (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, con la categoría «IE»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'LC (Preocupación menor) (evaluación UICN 2018)', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 7684, 6371424, 3, NULL, NULL, NULL
