    SELECT 'Ajo Amarillo', 'Allium rouyi', 'flora', 'Planta bulbosa', 'Edafoendemismo andaluz que habita suelos poco desarrollados, sobre rocas peridotíticas, de zonas termomediterráneas y con ombroclima subhúmedo- húmedo', 'Vulnerable', 'Planta herbácea, bulbosa. Escapo 20 a 27 cm, con 2-3 hojas basales, filiformes, glabras o con pelos reflejos en vainas y márgenes. Inflorescencia en umbela terminal, con espata de dos piezas más cortas que la inflorescencia; pedicelos más largos que los tépalos. Tépalos de 5-6 mm, amarillos con nervio medio verdoso, agudos, libres. Androceo con seis estambres incluidos; filamentos simples y anteras amarillas. Gineceo con un estilo ginobásico. Fruto cápsula de 3,5-4 mm, globosa.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, NULL, NULL, NULL, NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, que la cita como «Allium chrysonemum», con la categoría «VU»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Allium', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2011)', 'CR — En peligro crítico (Lista Roja española, 2010)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 2022, 2855704, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'achicoria falsa', 'Cheirolophus intybaceus', 'flora', 'Mata', 'Habita sobre acantilados y laderas de naturaleza margo-arenosa muy deleznables junto a la línea de costa, en el piso termomediterráneo de ombroclima seco', 'Vulnerable', 'Planta procumbente y multicaule, de base sufruticosa y hojas subcrasas, las inferiores liradopinnatipartidas y las superiores linear-lanceoladas. Tallos floríferos estriado-glandulosos, subáfilos y engrosados por debajo del capítulo. Brácteas del involucro oblongas, con apéndice semilunar y con 9-11 cilios. Aquenios de 4x2 mm, negruzcos, glabrescentes y con vilano de hasta 3 mm de longitud.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cheirolophus_intybaceus_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Cheirolophus', 'No evaluada en la Lista Roja mundial de la UICN', 'CR — En peligro crítico (Lista Roja española, 2010)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 3544, 3097063, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rana común', 'Pelophylax perezi', 'fauna', 'Anfibio', 'Charcas, balsas, acequias y tramos remansados con vegetación', 'LC', 'La rana verde ibérica, la más común y adaptable de nuestros anfibios: coloniza desde ramblas y balsas de riego hasta fuentes urbanas. Su canto es un cacareo entrecortado que forma coros al atardecer. Salta al agua al menor movimiento en la orilla.', NULL, 'Línea clara a lo largo del centro del lomo en muchos ejemplares; Canto entrecortado, como una risa o un cacareo; Salta al agua desde la orilla al notar movimiento', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelophylax_perezi_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, que la cita como «Pelophilax perezi» (errata del boletín: «Pelophilax» por «Pelophylax»); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Amphibia', 'Anura', 'Ranidae', 'Pelophylax', 'LC (Preocupación menor) (evaluación UICN 2022)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'Anexo VI (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007); UICN España: LC (Preocupación menor) (2002)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11964, 2426658, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cornicabra', 'Pistacia terebinthus', 'flora', 'Arbusto', 'Barrancos, umbrías y matorral alto sobre suelos frescos', 'Interés especial', 'Arbusto o arbolillo de hoja caduca, con hojas compuestas de foliolos grandes y brillantes y un raquis sin alas, lo que lo separa del lentisco. Suele presentar agallas rojizas y curvadas en forma de cuerno, provocadas por pulgones, que le dan el nombre.', NULL, 'Agallas rojizas curvadas como cuernos en las hojas; Pierde la hoja en invierno, al contrario que el lentisco; Hoja compuesta con foliolo terminal y raquis sin alas', 'Primavera a otoño (pierde la hoja en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistachier2.JPG?width=1280', 'greffer.net (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, con la categoría «IE»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC (Preocupación menor) (evaluación UICN 2016)', NULL, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 7130, 3190580, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Álamo blanco', 'Populus alba', 'flora', 'Árbol', 'Riberas, sotos y suelos con capa freática cercana', 'Interés especial', 'Árbol de ribera con el envés de las hojas cubierto de un fieltro blanco que hace que la copa parezca cambiar de color con el viento. La corteza es clara y con lenticelas romboidales oscuras. Rebrota de raíz con facilidad y forma bosquetes clonales.', NULL, 'Envés de la hoja blanco: la copa «platea» con el viento; Corteza clara con marcas romboidales oscuras; Retoños de raíz alrededor del pie principal', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Populus_alba_01.jpg?width=1280', 'la la means I love you (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, con la categoría «IE»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Malpighiales', 'Salicaceae', 'Populus', 'LC (Preocupación menor) (evaluación UICN 2018)', NULL, 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. Lista de especies forestales e híbiridos artificiales (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 7290, 3040233, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tomillo', 'Thymus antoninae', 'flora', 'Mata aromática', 'Tomillares y pastizales pedregosos de montaña sobre calizas', 'Interés especial', 'Tomillo endémico del sureste ibérico, de área muy restringida, que forma matitas bajas y grisáceas con espigas de flores rosadas o blanquecinas. Su rareza y la fragmentación de su hábitat lo convierten en una de las plantas más vulnerables del grupo.', NULL, 'Mata baja y grisácea, de hojas muy pequeñas; Espigas cortas de flores rosadas o blancas; Aroma a tomillo, más suave que el de sus parientes comunes', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/411356756/original.jpeg', 'Maël Taupin (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, con la categoría «IE»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Thymus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'NT — Casi amenazada (Lista Roja española, 2010)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 8896, 5607746, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Almez', 'Celtis australis', 'flora', 'Árbol', 'En vegas y riberas de ríos, sobre suelos húmedos y profundos de aluvión', 'Interés especial', 'Árbol caducifolio hasta de 30 m y amplia copa, con corteza muy lisa de color gris plateado, parecida a la piel de los elefantes. Ramas con frecuencia colgantes. Hojas 5-15 x 1,5-6 cm, simples, alternas, pecioladas, asimétricas en la base, lanceoladas, largamente acuminadas, aserradas, más o menos pelosas, con el haz verde oscuro y envés verde claro. Flores masculinas o hermafroditas, pequeñas y solitarias, poco vistosas, verdosas, con una sola envoltura floral y con un largo pedúnculo de 2-8 cm. Fruto de 8-12 mm, en drupa redondeada y con largo pedúnculo, color negro azulado en la madurez.', NULL, NULL, 'Abril a enero', 'https://commons.wikimedia.org/wiki/Special:FilePath/Celtis_australis_(2).JPG?width=1280', 'Marija Gajić (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (1 hábitat; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene, con la categoría «IE»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Cannabaceae', 'Celtis', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', NULL, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 3200, 2984492, 1, NULL, NULL, NULL
