    SELECT 'Alzacola', 'Cercotrichas galactotes', 'fauna', 'Ave', NULL, 'Vulnerable', 'Esta especie suele observarse en el suelo o posada en arbustos bajos. Es fácilmente reconocible por su larga cola, de coloración rojiza y extremo terminal con manchas blancas y negras, que frecuentemente alza, despliega y sacude de manera ostensible. También resulta distintivo su diseño facial, ya que posee una lista ocular fina oscura, que contrasta con una banda superciliar de color blanco crema. El resto de su plumaje presenta un tono ocre claro.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Mayo a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Agrobate_roux_au_Parc_National_de_l''Ichkeul_(Tunisia)%2C_crop.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Cercotrichas', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'EN — En peligro (Lista Roja española, 2004)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11327, NULL, 0, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ciervo', 'Cervus elaphus', 'fauna', 'Mamífero ungulado', NULL, 'Extinguida', 'Pelaje con predominio del color castaño uniforme, zona ventral más clara y escudo anal casi blanco flanqueado por bandas oscuras en ocasiones casi negras, cola corta de color oscuro. Los cervatillos tienen un pelaje característico con fondo castaño y manchas o “pintas” blancas que mantienen durante aproximadamente los tres primeros meses de vida. Dimorfismo sexual acentuado. Medidas corporales, CC: 160-220 cm (machos), 160-195 cm (hembras); CR: 90-120 cm (machos), 90-110 cm (hembras); Ps: 80-160 kg (machos), 50-100 kg (hembras). Los machos desarrollan a partir del primer año unas astas que utilizan en las luchas durante el período de celo. Presentan un tronco central que se ramifica en puntas o candiles en número variable. Las hembras carecen de astas y poseen dos pares de mamas en posición inguinal. Fórmula dentaria: 0.1.3.3/3.1.3.3, con un canino inferior modificado hasta adoptar forma de incisivo. Número de cromosomas (2n) = 68.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cervus_elaphus_Luc_Viatour_3.jpg?width=1280', 'Lviatour (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"Extinguida (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-22); Decreto n.º 55/2015, de 17 de abril, Plan de Gestión Integral de los espacios protegidos Red Natura 2000 del Noroeste de la Región de Murcia, volumen II §13.1 (ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla», ES6200004) (BORM n.º 109, de 14 de mayo de 2015): la norma la enumera en la ZEC «Sierras y Vega Alta del Segura y Ríos Alhárabe y Moratalla» (ES6200004), 11.026,83 ha, dentro de la cual esta Reserva Natural es un enclave de 248,8 ha —el 2,3 % de la superficie inventariada—: la ZEC abarca cuatro sectores (Río Segura, Alhárabe-Moratalla, El Salmerón y Sierra del Molino) y el espacio es solo un tramo del primero, así que la norma no afirma que la especie esté en Cañaverosa, sino en la ZEC que lo contiene; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Mammalia', 'Artiodactyla', 'Cervidae', 'Cervus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LC — Preocupación menor (Lista Roja española, 2007)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Extinguida (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 11195, NULL, 0, NULL, NULL, NULL
