SELECT sp.id, hb.id, v.evidence
FROM parks pk
JOIN (
    SELECT 'Sciurus vulgaris' scientific_name, 'bosques-galeria-de-92A0' habitat_slug, 'observada_gbif' evidence
    UNION ALL
    SELECT 'Sciurus vulgaris', 'galerias-y-matorrales-92D0', 'observada_gbif'
