JOIN species sp ON sp.park_id = pk.id AND sp.scientific_name = v.scientific_name
JOIN habitats hb ON hb.park_id = pk.id AND hb.slug = v.habitat_slug
WHERE pk.slug = 'sotos-y-bosques-de-ribera-de-canaverosa'
ON DUPLICATE KEY UPDATE evidence = VALUES(evidence);

-- ------------------------------------------------------------------------------------------------
-- 5. Comprobación posterior. Debe devolver exactamente los recuentos de la cabecera.
-- ------------------------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM parks WHERE slug = 'sotos-y-bosques-de-ribera-de-canaverosa') AS espacio,
    (SELECT COUNT(*) FROM habitats h JOIN parks p ON p.id = h.park_id WHERE p.slug = 'sotos-y-bosques-de-ribera-de-canaverosa') AS habitats,
    (SELECT COUNT(*) FROM species s JOIN parks p ON p.id = s.park_id WHERE p.slug = 'sotos-y-bosques-de-ribera-de-canaverosa') AS especies,
    (SELECT COUNT(*) FROM species_habitats sh JOIN species s ON s.id = sh.species_id JOIN parks p ON p.id = s.park_id WHERE p.slug = 'sotos-y-bosques-de-ribera-de-canaverosa') AS vinculos;
